        let compressionQuality: CGFloat
        switch quality {
        case .good: compressionQuality = 0.85
        case .moderate: compressionQuality = 0.7
        case .poor: compressionQuality = 0.5
        case .offline: compressionQuality = 0.85 // will be queued, use high quality
        }
        return image.jpegData(compressionQuality: compressionQuality)
    }

    /// Fixed-quality JPEG data for consistent hashing (cache key)
    static func hashableJPEGData(_ image: UIImage) -> Data? {
        image.jpegData(compressionQuality: 0.85)
    }

